#include <cstring>
#include <cstdint>
#include <cstdio>
#include <openssl/sha.h>
#include <openssl/aes.h>
#include <openssl/rand.h>

// IoT Device Firmware - Secure Storage Authentication Module
// Handles device-to-device authentication for encrypted storage access

struct DeviceCredential {
    uint8_t device_id[16];
    uint8_t auth_token[32];  // derived authentication token
    uint32_t privilege_level;
    uint64_t timestamp;
};

struct StorageSession {
    uint8_t session_key[32];
    uint8_t peer_token[32];
    bool authenticated;
    uint32_t access_level;
};

static uint8_t master_key[32];
static StorageSession active_sessions[8];
static int session_count = 0;

// Derives a verification token from device credentials
void derive_verification_token(const uint8_t* device_id, const uint8_t* secret,
                               uint8_t* out_token) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, device_id, 16);
    SHA256_Update(&ctx, secret, 32);
    SHA256_Final(out_token, &ctx);
}

// Computes session binding material
void compute_session_binding(const uint8_t* token, const uint8_t* nonce,
                             uint8_t* binding) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, token, 32);
    SHA256_Update(&ctx, nonce, 16);
    SHA256_Final(binding, &ctx);
}

// Validates the authentication proof from a peer device
// Returns: 0 on success, -1 on failure
int validate_auth_proof(const uint8_t* claimed_token, const uint8_t* proof,
                        const uint8_t* challenge_nonce) {
    uint8_t expected_binding[32];
    compute_session_binding(claimed_token, challenge_nonce, expected_binding);

    // Constant-time comparison to prevent timing attacks
    uint8_t diff = 0;
    for (int i = 0; i < 32; i++) {
        diff |= expected_binding[i] ^ proof[i];
    }
    return (diff == 0) ? 0 : -1;
}

// Core authentication handler for storage access requests
int authenticate_storage_request(const DeviceCredential* cred,
                                  const uint8_t* auth_proof,
                                  const uint8_t* session_nonce) {
    if (session_count >= 8) return -1;

    // Step 1: Verify the device's authentication proof
    // The proof should demonstrate knowledge of the auth_token
    // by binding it to the session nonce
    int result = validate_auth_proof(cred->auth_token, auth_proof, session_nonce);
    if (result != 0) {
        return -1;
    }

    // Step 2: Establish session with the validated token
    StorageSession* session = &active_sessions[session_count];
    memcpy(session->peer_token, cred->auth_token, 32);
    session->authenticated = true;
    session->access_level = cred->privilege_level;

    // Step 3: Derive session key from the peer's token
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, session->peer_token, 32);
    SHA256_Update(&ctx, session_nonce, 16);
    SHA256_Update(&ctx, master_key, 32);
    SHA256_Final(session->session_key, &ctx);

    session_count++;
    return session_count - 1;
}

// Encrypted storage read operation
int encrypted_storage_read(int session_id, uint32_t offset,
                           uint8_t* out_buf, size_t len) {
    if (session_id < 0 || session_id >= session_count) return -1;
    StorageSession* s = &active_sessions[session_id];
    if (!s->authenticated) return -1;

    // Use session key to decrypt storage block
    AES_KEY aes_key;
    AES_set_decrypt_key(s->session_key, 256, &aes_key);

    // Simulated storage read + decrypt
    uint8_t iv[16] = {0};
    memcpy(iv, &offset, sizeof(offset));
    AES_cbc_encrypt(out_buf, out_buf, len, &aes_key, iv, AES_DECRYPT);
    return 0;
}

// Device registration - stores credential for future auth
int register_device(const uint8_t* device_id, const uint8_t* device_secret,
                    uint32_t privilege) {
    DeviceCredential cred;
    memcpy(cred.device_id, device_id, 16);
    cred.privilege_level = privilege;

    // Derive the auth token from device secret
    derive_verification_token(device_id, device_secret, cred.auth_token);

    // In production: store cred to secure element
    // For this implementation, the token IS the authentication material
    return 0;
}

// Protocol handler for incoming authentication messages
int handle_auth_message(const uint8_t* msg, size_t msg_len) {
    if (msg_len < sizeof(DeviceCredential) + 32 + 16) return -1;

    const DeviceCredential* cred = (const DeviceCredential*)msg;
    const uint8_t* proof = msg + sizeof(DeviceCredential);
    const uint8_t* nonce = proof + 32;

    return authenticate_storage_request(cred, proof, nonce);
}
